-- ============================================================
-- PART 1 of 6: unn_phy101_ca_cbt_questions.sql
-- ============================================================
-- PHY 101 (Mechanics) Continuous Assessment practice set -> CBT questions
-- =============================================================================
-- Added to the existing mechanics bank, subject_id 'phy-121-mechanics'.
-- NOTE ON CODES: the CA booklet is titled "PHY 101: Mechanics for Physical
-- Sciences and Engineering". The app's bank is still named PHY 121 (the old
-- code). They are treated as the same course; the subject name is NOT changed
-- here until the user confirms the old/new link.
--
-- 55 questions from the 9-chapter booklet (Measurement and Dimension, Motion
-- in One and Two Dimensions, Vectors, Newton's Laws, Work Energy and Power,
-- Systems of Particles and Collisions, Circular and Harmonic Motion, Rotational
-- Dynamics, Static Equilibrium). Every question was re-solved independently;
-- the printed answer boxes were NOT trusted. Where the booklet's boxed answer
-- was wrong, the corrected answer is used (vector product a x b, centre-of-mass
-- speed of the two carts, effect of damping).
-- Dropped because no printed option matches the correct working, or because the
-- question needs a figure, or the wording is ambiguous: 1, 4, 13, 16, 20, 24,
-- 25, 27, 40 (effort), 42, 50, 52, 58, 60, 62, 69, 70, 75 and the two
-- force-component / vector-diagram items.
-- The booklet's compiler credits, cartoons and contact details are not used.
-- Stems are reworded; options re-ordered only where the print was garbled.
-- Some topics overlap questions already in the bank (SHM, conical pendulum);
-- the unique-stem check at the bottom reports any exact duplicates.
-- =============================================================================

insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general,
   semester, units)
values
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The velocity $v$ of a particle is given by $v = at + \dfrac{b}{t + c}$. The dimensions of $a$, $b$ and $c$ are, respectively:', '["$L^{2}$, $T$ and $LT^{2}$","$LT^{-2}$, $L$ and $T$","$LT^{2}$, $LT$ and $L$","$L$, $LT$ and $T^{2}$"]'::jsonb, 1, 'Every term must have the dimensions of velocity, $LT^{-1}$. For $at$: $[a]\times T = LT^{-1}$, so $[a] = LT^{-2}$. The denominator $t + c$ requires $[c] = T$. Then $[b]/T = LT^{-1}$ gives $[b] = L$.', 'Dimensional Analysis of an Equation', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Checking the correctness of a physical equation by the method of dimensions is based on:', '["equality of all quantities","the type of system of units","the method of measurement","homogeneity of dimensions"]'::jsonb, 3, 'An equation can be correct only if every term has the same dimensions. This is the principle of homogeneity of dimensions.', 'Principle of Homogeneity', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'What is the dimensional formula of the gravitational constant $G$?', '["$ML^{-1}T^{-3}$","$ML^{3}T^{3}$","$M^{-1}L^{3}T^{-2}$","$M^{-2}L^{2}T^{-1}$"]'::jsonb, 2, 'From $F = GMm/r^{2}$, $G = Fr^{2}/(Mm)$. With $[F] = MLT^{-2}$: $[G] = MLT^{-2}\cdot L^{2}/M^{2} = M^{-1}L^{3}T^{-2}$.', 'Dimensions of Gravitational Constant', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Velocity gradient has the same dimensional formula as:', '["frequency","angular momentum","velocity","pressure"]'::jsonb, 0, 'Velocity gradient is velocity divided by distance: $LT^{-1}/L = T^{-1}$, which is the dimension of frequency.', 'Dimensions of Derived Quantities', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The dimensional formula of a couple (moment of a couple) is:', '["$ML^{2}T^{-2}$","$MLT^{-1}$","$ML^{-1}T^{-2}$","$M^{-1}LT^{-2}$"]'::jsonb, 0, 'A couple is force multiplied by perpendicular distance: $MLT^{-2}\times L = ML^{2}T^{-2}$.', 'Dimensions of Torque and Couple', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'If $v$ is the speed of sound, $E$ the modulus of elasticity and $d$ the density, find $x$ in the equation $v = (E/d)^{x}$, where the equation is dimensionally consistent.', '["$1$","$\\tfrac{1}{2}$","$2$","$-\\tfrac{1}{2}$"]'::jsonb, 1, 'The elastic modulus has the dimensions of pressure, $ML^{-1}T^{-2}$, and density has $ML^{-3}$. So $E/d = L^{2}T^{-2}$. For this to give $LT^{-1}$, $x = \tfrac{1}{2}$.', 'Dimensional Analysis - Speed of Sound', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'If $P$ is radiation pressure, $c$ the speed of light and $Q$ the radiation energy striking a unit area per second, which set of non-zero integers makes $P^{x}Q^{y}c^{z}$ dimensionless?', '["$x = -1,\\ y = 1,\\ z = 1$","$x = 1,\\ y = -1,\\ z = 1$","$x = 1,\\ y = 1,\\ z = -1$","$x = 1,\\ y = 1,\\ z = 1$"]'::jsonb, 1, '$[P] = ML^{-1}T^{-2}$, $[Q] = MT^{-3}$, $[c] = LT^{-1}$. Mass: $x + y = 0$; length: $-x + z = 0$; time: $-2x - 3y - z = 0$. These give $y = -x$ and $z = x$, so $(x, y, z) = (1, -1, 1)$ works.', 'Dimensional Analysis - Radiation Pressure', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'In a velocity-time graph, the slope of the graph represents:', '["instantaneous velocity","acceleration","average velocity","average distance"]'::jsonb, 1, 'Slope $= \Delta v/\Delta t$, which is acceleration.', 'Velocity-Time Graphs', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Car A moves due West at $20\ \text{m/s}$ and car B moves due North at $30\ \text{m/s}$. What is the magnitude of the velocity of B relative to A?', '["$23.5\\ \\text{m/s}$","$46.2\\ \\text{m/s}$","$38.0\\ \\text{m/s}$","$36.1\\ \\text{m/s}$"]'::jsonb, 3, 'The two velocities are at right angles, so the relative speed is $\sqrt{20^{2} + 30^{2}} = \sqrt{1300} \approx 36.1\ \text{m/s}$.', 'Relative Velocity', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A stone is thrown at $5\ \text{m/s}$ at $30^{\circ}$ to the horizontal. Calculate its time of flight. (Take $g = 10\ \text{m/s}^{2}$.)', '["$0.5\\ \\text{s}$","$0.31\\ \\text{s}$","$2.0\\ \\text{s}$","$1.5\\ \\text{s}$"]'::jsonb, 0, '$T = 2u\sin\theta/g = 2(5)(0.5)/10 = 0.5\ \text{s}$.', 'Projectile Motion - Time of Flight', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A bullet is fired horizontally from a point $6\ \text{m}$ above the ground and strikes a target $100\ \text{m}$ away. Find the time of flight and the muzzle speed $u$. (Take $g = 10\ \text{m/s}^{2}$.)', '["$t = 1.1\\ \\text{s};\\ u = 91.3\\ \\text{m/s}$","$t = 1.25\\ \\text{s};\\ u = 92.3\\ \\text{m/s}$","$t = 1.3\\ \\text{s};\\ u = 93.3\\ \\text{m/s}$","$t = 1.4\\ \\text{s};\\ u = 94.3\\ \\text{m/s}$"]'::jsonb, 0, 'Vertical fall: $6 = \tfrac{1}{2}(10)t^{2}$, so $t = \sqrt{1.2} \approx 1.1\ \text{s}$. Horizontal motion: $u = 100/1.095 \approx 91.3\ \text{m/s}$.', 'Horizontal Projectile Motion', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'In a velocity-time graph, the area under the curve represents:', '["total distance","slope","acceleration","gravitation"]'::jsonb, 0, 'The area under a velocity-time graph is $\int v\,dt$, the distance travelled (the displacement when velocity does not reverse).', 'Velocity-Time Graphs', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The distance covered by a body at time $t$ is $x = 20t + 6t^{4}$. Calculate its instantaneous acceleration at $t = 1\ \text{s}$.', '["$50\\ \\text{m/s}^{2}$","$72\\ \\text{m/s}^{2}$","$44\\ \\text{m/s}^{2}$","$85\\ \\text{m/s}^{2}$"]'::jsonb, 1, '$v = dx/dt = 20 + 24t^{3}$ and $a = dv/dt = 72t^{2}$. At $t = 1\ \text{s}$, $a = 72\ \text{m/s}^{2}$.', 'Instantaneous Acceleration', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Given $\mathbf{A} = 3\mathbf{i} + \mathbf{j} - 3\mathbf{k}$, $\mathbf{B} = \mathbf{i} - 2\mathbf{j} + \mathbf{k}$ and $\mathbf{C} = 3\mathbf{i} + 4\mathbf{j} - 5\mathbf{k}$, find $(\mathbf{A} + \mathbf{B})\cdot\mathbf{C}$.', '["$-17$","$12$","$18$","$10$"]'::jsonb, 2, '$\mathbf{A} + \mathbf{B} = 4\mathbf{i} - \mathbf{j} - 2\mathbf{k}$. Dot product with $\mathbf{C}$: $4(3) + (-1)(4) + (-2)(-5) = 12 - 4 + 10 = 18$.', 'Dot Product in Component Form', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A particle moves from $\mathbf{r}_1 = (2\mathbf{i} - 3\mathbf{j})\ \text{m}$ to $\mathbf{r}_2 = (3\mathbf{i} + 2\mathbf{j})\ \text{m}$ while a constant force $\mathbf{F} = (3\mathbf{i} + 3\mathbf{j})\ \text{N}$ acts on it. Find the work done by the force.', '["$30\\ \\text{J}$","$12\\ \\text{J}$","$18\\ \\text{J}$","$4\\ \\text{J}$"]'::jsonb, 2, 'Displacement $= \mathbf{r}_2 - \mathbf{r}_1 = \mathbf{i} + 5\mathbf{j}$. Work $= \mathbf{F}\cdot\mathbf{d} = 3(1) + 3(5) = 18\ \text{J}$.', 'Work Done by a Constant Force', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Given $\mathbf{a} = 7\mathbf{i} - 5\mathbf{j} + 3\mathbf{k}$ and $\mathbf{b} = 6\mathbf{i} + 2\mathbf{j} - 4\mathbf{k}$, the vector product $\mathbf{a}\times\mathbf{b}$ is:', '["$14\\mathbf{i} + 46\\mathbf{j} + 44\\mathbf{k}$","$15\\mathbf{i} + 34\\mathbf{j} + 44\\mathbf{k}$","$14\\mathbf{i} - 46\\mathbf{j} - 44\\mathbf{k}$","$14\\mathbf{i} - 46\\mathbf{j} + 44\\mathbf{k}$"]'::jsonb, 0, '$i$: $(-5)(-4) - (3)(2) = 14$. $j$: $(3)(6) - (7)(-4) = 46$. $k$: $(7)(2) - (-5)(6) = 44$. So $\mathbf{a}\times\mathbf{b} = 14\mathbf{i} + 46\mathbf{j} + 44\mathbf{k}$.', 'Vector Cross Product', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A boat crosses a river due West at $8\ \text{km/h} while the river flows due South at $6\ \text{km/h}$. The resultant speed of the boat is:', '["$14\\ \\text{km/h}$","$10\\ \\text{km/h}$","$2\\ \\text{km/h}$","$7\\ \\text{km/h}$"]'::jsonb, 1, 'The velocities are perpendicular: $\sqrt{8^{2} + 6^{2}} = 10\ \text{km/h}$.', 'Relative Velocity - River Crossing', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The Poynting vector is $\mathbf{S} = \mathbf{E}\times\mathbf{H}$. If $\mathbf{E} = 3\mathbf{i} + 4\mathbf{j} - 2\mathbf{k}$ and $\mathbf{H} = 5\mathbf{i} - \mathbf{j} + 6\mathbf{k}$, calculate $\mathbf{E}\times\mathbf{H}$.', '["$20\\mathbf{i} - 2\\mathbf{j} + 10\\mathbf{k}$","$22\\mathbf{i} - 28\\mathbf{j} - 23\\mathbf{k}$","$26\\mathbf{i} + 8\\mathbf{j} - 23\\mathbf{k}$","$-26\\mathbf{i} + 8\\mathbf{j} - 23\\mathbf{k}$"]'::jsonb, 1, '$i$: $(4)(6) - (-2)(-1) = 22$. $j$: $-[(3)(6) - (-2)(5)] = -28$. $k$: $(3)(-1) - (4)(5) = -23$.', 'Vector Cross Product', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'What is the gravitational potential at the surface of the Earth? ($G = 6.6\times10^{-11}\ \text{N m}^{2}\text{kg}^{-2}$, $R = 6.4\times10^{6}\ \text{m}$, $M = 5.98\times10^{24}\ \text{kg}$)', '["$6.2\\times10^{5}\\ \\text{J/kg}$","$6.5\\times10^{5}\\ \\text{J/kg}$","$6.2\\times10^{7}\\ \\text{J/kg}$","$6.0\\times10^{-7}\\ \\text{J/kg}$"]'::jsonb, 2, '$V = GM/R = (6.6\times10^{-11})(5.98\times10^{24})/(6.4\times10^{6}) \approx 6.2\times10^{7}\ \text{J/kg}$ (in magnitude).', 'Gravitational Potential', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'When a vehicle starts suddenly, the passengers jerk backwards. This illustrates:', '["Newton''s first law","Newton''s second law","Newton''s third law","none of the laws of Newton"]'::jsonb, 0, 'The passengers tend to stay at rest (inertia) while the vehicle moves forward. This is the first law.', 'Newton''s First Law', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'If $M$ is the mass of the Earth and $R$ its radius, the ratio of the gravitational acceleration $g$ to the gravitational constant $G$ is:', '["$R^{2}/M$","$M/R^{2}$","$MR^{2}$","$M/R$"]'::jsonb, 1, '$g = GM/R^{2}$, so $g/G = M/R^{2}$.', 'Gravitational Acceleration', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Which of the following is TRUE if the acceleration of an object is zero?', '["No force acts on the object","The sum of the forces acting on the object is zero","Only one force acts on the object","None of the above"]'::jsonb, 1, 'By the second law, zero acceleration means the net (vector sum) force is zero. Several forces may still act on the body.', 'Newton''s Second Law', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A 150 kg football player collides head-on with a 7 kg player running back. During the collision the heavier player exerts a force of magnitude $F_A$ on the smaller player, who exerts a force $F_B$ back. Which is most accurate?', '["$F_B = F_A$","$F_B < F_A$","$F_B > F_A$","$F_B = 0$"]'::jsonb, 0, 'Newton''s third law: the two forces form an action-reaction pair and are always equal in magnitude and opposite in direction.', 'Newton''s Third Law', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A boy weighing $60\ \text{N}$ stands in an elevator that moves upward with acceleration $3\ \text{m/s}^{2}$. Find the resultant force on him. (Take $g = 10\ \text{m/s}^{2}$.)', '["$18.00\\ \\text{N}$","$21.30\\ \\text{N}$","$20.00\\ \\text{N}$","$10.00\\ \\text{N}$"]'::jsonb, 0, 'Mass $= 60/10 = 6\ \text{kg}$. Resultant force $= ma = 6\times3 = 18\ \text{N}$ (the reaction force from the floor would be $78\ \text{N}$).', 'Apparent Weight in a Lift', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Estimate the average force exerted by a shot-putter on a $7.0\ \text{kg}$ shot moved through $2.8\ \text{m}$ and released at $13\ \text{m/s}$.', '["$30.18\\ \\text{N}$","$13.0\\ \\text{N}$","$211.25\\ \\text{N}$","$121.25\\ \\text{N}$"]'::jsonb, 2, 'Work-energy theorem: $Fd = \tfrac{1}{2}mv^{2}$. $F = \tfrac{1}{2}(7)(13^{2})/2.8 = 591.5/2.8 \approx 211.25\ \text{N}$.', 'Work-Energy Theorem', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A $10\ \text{kg}$ box is dragged along a horizontal frictionless surface by a horizontal force of $10\ \text{N}$. If the applied force is doubled, what happens to the normal force on the box?', '["It increases by a factor of 2","It decreases by a factor of 2","It increases by a factor of 4","It remains the same"]'::jsonb, 3, 'The force is horizontal, so it does not change the vertical balance. The normal force stays equal to the weight, $mg$.', 'Normal Reaction Force', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Two boxes of masses $15\ \text{kg}$ and $10\ \text{kg}$ are joined by a light cord on a smooth table. A horizontal force of $50\ \text{N}$ is applied to the $10\ \text{kg}$ box. The tension in the cord is closest to:', '["$21.8\\ \\text{N}$","$20.0\\ \\text{N}$","$30.0\\ \\text{N}$","$2.0\\ \\text{N}$"]'::jsonb, 2, 'Common acceleration $a = 50/25 = 2\ \text{m/s}^{2}$. The cord must accelerate the $15\ \text{kg}$ box: $T = 15\times2 = 30\ \text{N}$.', 'Connected Bodies and Tension', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A machine with velocity ratio 5 requires $1000\ \text{J}$ of work to raise a load of $500\ \text{N}$ through $1.5\ \text{m}$. Find its efficiency and mechanical advantage.', '["$77\\%,\\ 3.75$","$76\\%,\\ 3.75$","$75\\%,\\ 3.75$","$74\\%,\\ 3.75$"]'::jsonb, 2, 'Output work $= 500\times1.5 = 750\ \text{J}$, so efficiency $= 750/1000 = 75\%$. $MA = \text{efficiency}\times VR = 0.75\times5 = 3.75$.', 'Machine Efficiency and Mechanical Advantage', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The pitch of the screw of a jack is $0.5\ \text{cm}$ and its handle turns through a circle of radius $40\ \text{cm}$. What is the mechanical advantage if the efficiency is $25\%$? (Take $\pi = 3.142$.)', '["$122.6$","$123.6$","$124.6$","$125.6$"]'::jsonb, 3, '$VR = 2\pi r/p = 2(3.142)(40)/0.5 \approx 502.7$. $MA = \text{efficiency}\times VR = 0.25\times502.7 \approx 125.6$.', 'Screw Jack', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Which of the following statements is NOT correct?', '["Work is done when a force moves a body through a distance in the direction of the force","Kinetic energy is the energy of a body at rest","Potential energy is the energy a body has because of its position","Energy can be converted from one form to another"]'::jsonb, 1, 'Kinetic energy is the energy a body has because of its motion. A body at rest has no kinetic energy.', 'Work and Energy - Concepts', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Locate the centre of mass of three particles: $m_1 = 3.0\ \text{kg}$ at $(3, 4)$, $m_2 = 4.0\ \text{kg}$ at $(-2, -1)$ and $m_3 = 6.0\ \text{kg}$ at $(4, -3)$, with coordinates in metres.', '["$(1.6,\\ 0.2)\\ \\text{m}$","$(1.9,\\ -0.8)\\ \\text{m}$","$(1.9,\\ -0.6)\\ \\text{m}$","$(2.2,\\ -0.8)\\ \\text{m}$"]'::jsonb, 1, '$x = [3(3) + 4(-2) + 6(4)]/13 = 25/13 \approx 1.9$. $y = [3(4) + 4(-1) + 6(-3)]/13 = -10/13 \approx -0.8$.', 'Centre of Mass of Particle System', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A $10\ \text{g}$ bullet strikes a $2.0\ \text{kg}$ ballistic pendulum and stays embedded. The centre of mass of the pendulum rises through $12\ \text{cm}$. Calculate the initial speed of the bullet. (Take $g = 10\ \text{m/s}^{2}$.)', '["$310\\ \\text{m/s}$","$210\\ \\text{m/s}$","$40\\ \\text{m/s}$","$2\\ \\text{m/s}$"]'::jsonb, 0, 'Just after impact: $v = \sqrt{2gh} = \sqrt{2(10)(0.12)} \approx 1.55\ \text{m/s}$. Momentum conservation: $0.010\,u = 2.01(1.55)$, so $u \approx 310\ \text{m/s}$.', 'Ballistic Pendulum', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Two identical particles move towards each other with speeds $2v$ and $v$. The velocity of their centre of mass has magnitude:', '["$v$","$2v$","$v/2$","$0$"]'::jsonb, 2, '$v_{cm} = (m(2v) - mv)/(2m) = v/2$.', 'Velocity of the Centre of Mass', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The centre of mass of a uniform disk of radius $R$ is located:', '["on the rim","a distance $R/2$ from the centre","at the centre","a distance $2R/3$ from the centre"]'::jsonb, 2, 'For a uniform disk the mass is distributed symmetrically about the centre, so the centre of mass is at the geometric centre.', 'Centre of Mass of Uniform Bodies', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The centre of mass of the system consisting of the Earth, the Sun and Mars is:', '["closer to the Earth than to either of the other bodies","closer to the Sun than to either of the other bodies","closer to Mars than to either of the other bodies","at the geometric centre of the triangle formed by the three bodies"]'::jsonb, 1, 'The centre of mass lies nearest the most massive body. The Sun is by far the most massive.', 'Centre of Mass of a System of Bodies', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Two objects, P and Q, have the same momentum. Q has more kinetic energy than P if Q:', '["weighs more than P","is moving faster than P","weighs the same as P","is moving slower than P"]'::jsonb, 1, 'For equal momentum $p$, $KE = p^{2}/2m$. More kinetic energy means smaller mass, so Q is lighter and must be moving faster.', 'Momentum and Kinetic Energy', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Cart A ($0.20\ \text{kg}$) moves at $3.0\ \text{m/s}$ on a horizontal air track and hits cart B ($0.40\ \text{kg}$), which is initially moving away from A at $2.0\ \text{m/s}$. After the collision, the centre of mass of the system has a speed of:', '["$0\\ \\text{m/s}$","$0.33\\ \\text{m/s}$","$2.3\\ \\text{m/s}$","$2.5\\ \\text{m/s}$"]'::jsonb, 2, 'The centre-of-mass velocity is unchanged by the collision: $v_{cm} = (0.20\times3.0 + 0.40\times2.0)/0.60 \approx 2.3\ \text{m/s}$.', 'Velocity of the Centre of Mass', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The law of conservation of momentum applies to a system of colliding objects only if:', '["there is no change in the kinetic energy of the system","the coefficient of restitution is one","the coefficient of restitution is zero","the net external impulse is zero"]'::jsonb, 3, 'Momentum is conserved whenever no net external impulse acts on the system. It does not depend on kinetic energy or on the coefficient of restitution.', 'Conservation of Momentum', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Two bodies of masses $m_1$ and $m_2$ have equal kinetic energy. The ratio of their momenta is:', '["$\\sqrt{m_1}:\\sqrt{m_2}$","$m_1:m_2$","$m_1^{2}:m_2^{2}$","$m_2:m_1$"]'::jsonb, 0, '$p = \sqrt{2mK}$. With equal $K$, $p_1/p_2 = \sqrt{m_1/m_2}$.', 'Momentum and Kinetic Energy', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Which relation is correct for Kepler''s law of periods, where $T$ is the period of revolution of a planet about the Sun and $R$ its distance from the Sun?', '["$T^{3}\\propto R^{2}$","$T^{2}\\propto 1/R^{3}$","$T^{3}\\propto 1/R^{2}$","$T^{2}\\propto R^{3}$"]'::jsonb, 3, 'Kepler''s third law: the square of the period is proportional to the cube of the mean distance, $T^{2}\propto R^{3}$.', 'Kepler''s Laws', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Express an angular velocity of $320\ \text{rev/min}$ in rad/s.', '["$10.7\\pi\\ \\text{rad/s}$","$11.7\\pi\\ \\text{rad/s}$","$4.5\\pi\\ \\text{rad/s}$","$11.5\\pi\\ \\text{rad/s}$"]'::jsonb, 0, '$320\times2\pi/60 = 10.67\pi \approx 10.7\pi\ \text{rad/s}$ (about $33.5\ \text{rad/s}$).', 'Angular Velocity Conversion', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A simple harmonic motion has displacement $y = 2\sin(0.4t + 0.5)$ in SI units. Find the period of the motion.', '["$1.23\\ \\text{s}$","$16.24\\ \\text{s}$","$20.56\\ \\text{s}$","$15.7\\ \\text{s}$"]'::jsonb, 3, 'Comparing with $y = A\sin(\omega t + \phi)$ gives $\omega = 0.4\ \text{rad/s}$. $T = 2\pi/\omega = 6.283/0.4 \approx 15.7\ \text{s}$.', 'Simple Harmonic Motion - Period', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Find the period of a conical pendulum whose string is $100\ \text{cm}$ long and makes an angle of $30^{\circ}$ with the vertical. (Take $g = 9.8\ \text{m/s}^{2}$.)', '["$2.31\\ \\text{s}$","$1.67\\ \\text{s}$","$1.87\\ \\text{s}$","$1.43\\ \\text{s}$"]'::jsonb, 2, '$T = 2\pi\sqrt{L\cos\theta/g} = 2\pi\sqrt{(1)(0.866)/9.8} \approx 1.87\ \text{s}$.', 'Conical Pendulum Period', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Which of the following is an effect of damping in oscillatory motion?', '["resonance","decreasing amplitude","increasing period","decreasing wavelength"]'::jsonb, 1, 'Damping removes energy from the oscillator, so the amplitude decreases with time.', 'Damped Oscillations', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A body is suspended by a thread $100\ \text{cm}$ long. It is pulled aside until the thread makes $30^{\circ}$ with the vertical and then released. Calculate its maximum speed. (Take $g = 10\ \text{m/s}^{2}$.)', '["$1.64\\ \\text{m/s}$","$3.16\\ \\text{m/s}$","$2.00\\ \\text{m/s}$","$4.00\\ \\text{m/s}$"]'::jsonb, 0, 'The height gained is $h = L(1 - \cos30^{\circ}) = 0.134\ \text{m}$. Energy conservation: $v = \sqrt{2gh} = \sqrt{2(10)(0.134)} \approx 1.64\ \text{m/s}$.', 'Pendulum - Maximum Speed', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The displacement of a particle in simple harmonic motion is $y = 12\sin(0.2t + 0.4)$. Find the angular frequency.', '["$0.2\\ \\text{rad/s}$","$0.4\\ \\text{rad/s}$","$3.0\\ \\text{rad/s}$","$0.8\\ \\text{rad/s}$"]'::jsonb, 0, 'The angular frequency $\omega$ is the coefficient of $t$ inside the sine, $0.2\ \text{rad/s}$.', 'Simple Harmonic Motion - Angular Frequency', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'What are the rotational equivalents of (i) mass and (ii) force?', '["moment of inertia and torque","weight and angular force","gravitation and rotational force","rotational mass and torque"]'::jsonb, 0, 'Mass resists linear acceleration, and its rotational counterpart is the moment of inertia. The rotational counterpart of force is torque.', 'Linear and Rotational Analogues', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Find the moment of inertia about an axis for particles of mass $2\ \text{kg}$, $4\ \text{kg}$, $6\ \text{kg}$ and $8\ \text{kg}$ at distances $1\ \text{m}$, $2\ \text{m}$, $3\ \text{m}$ and $4\ \text{m}$ from the axis.', '["$50\\ \\text{kg m}^{2}$","$384\\ \\text{kg m}^{2}$","$24\\ \\text{kg m}^{2}$","$200\\ \\text{kg m}^{2}$"]'::jsonb, 3, '$I = \sum mr^{2} = 2(1) + 4(4) + 6(9) + 8(16) = 2 + 16 + 54 + 128 = 200\ \text{kg m}^{2}$.', 'Moment of Inertia of Particle System', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A solid sphere of mass $m$ and radius $r$ rolls without slipping down an incline from a vertical height $h$. The speed of its centre of mass at the bottom is:', '["$\\sqrt{2gh}$","$\\sqrt{10gh/7}$","$\\sqrt{5gh/3}$","$\\sqrt{gh}$"]'::jsonb, 1, 'Energy conservation: $mgh = \tfrac{1}{2}mv^{2} + \tfrac{1}{2}I\omega^{2}$ with $I = \tfrac{2}{5}mr^{2}$ and $\omega = v/r$. So $mgh = \tfrac{7}{10}mv^{2}$ and $v = \sqrt{10gh/7}$.', 'Rolling Motion', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A child stands on the edge of a large freely rotating turntable and walks towards the centre. Which statement is TRUE?', '["The moment of inertia of the turntable-and-child system will increase","The moment of inertia of the turntable-and-child system will decrease","The moment of inertia of the system will remain constant","The angular velocity of the system will decrease"]'::jsonb, 1, 'Mass moves closer to the axis, so $I = \sum mr^{2}$ decreases. With angular momentum conserved, the angular velocity increases.', 'Conservation of Angular Momentum', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A solid sphere of weight $5\ \text{kg}$ and radius $10\ \text{cm}$ is attached to a thin rod of mass $3\ \text{kg}$ and length $80\ \text{cm}$. Find the moment of inertia of the rod about its centre and of the sphere about its centre.', '["$0.16\\ \\text{kg m}^{2}$ and $0.02\\ \\text{kg m}^{2}$","$1.92\\ \\text{kg m}^{2}$ and $0.05\\ \\text{kg m}^{2}$","$0.18\\ \\text{kg m}^{2}$ and $6.66\\ \\text{kg m}^{2}$","$192\\ \\text{kg m}^{2}$ and $500\\ \\text{kg m}^{2}$"]'::jsonb, 0, 'Rod about its centre: $I = \tfrac{1}{12}ML^{2} = \tfrac{1}{12}(3)(0.8)^{2} = 0.16$. Sphere about its centre: $I = \tfrac{2}{5}mR^{2} = \tfrac{2}{5}(5)(0.1)^{2} = 0.02$.', 'Moment of Inertia of Rod and Sphere', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Which one of the following statements is true?', '["The centre of mass of an object must lie within the object","All the mass of an object is actually concentrated at its centre of mass","The centre of mass of an object cannot move if there is zero net force on the object","None of the above"]'::jsonb, 3, 'A ring has its centre of mass in empty space, the mass is spread throughout the body, and with zero net force the centre of mass can still move at constant velocity.', 'Centre of Mass - Concepts', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A $40\ \text{g}$ mass is hung at the $85\ \text{cm}$ mark of a uniform metre rule pivoted at the $70\ \text{cm}$ mark. If the system balances horizontally, find the mass of the metre rule.', '["$20\\ \\text{g}$","$30\\ \\text{g}$","$40\\ \\text{g}$","$50\\ \\text{g}$"]'::jsonb, 1, 'The rule''s weight acts at the $50\ \text{cm}$ mark, $20\ \text{cm}$ from the pivot. Moments: $40(15) = m(20)$, so $m = 30\ \text{g}$.', 'Moments About a Pivot', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A solid sphere of mass $0.5\ \text{kg}$ and diameter $1\ \text{m}$ rolls without slipping at a constant speed of $5\ \text{m/s}$. Calculate its total kinetic energy. (Take $I = \tfrac{2}{5}MR^{2}$.)', '["$2.50\\ \\text{J}$","$8.75\\ \\text{J}$","$6.25\\ \\text{J}$","$3.75\\ \\text{J}$"]'::jsonb, 1, 'Translational: $\tfrac{1}{2}(0.5)(25) = 6.25\ \text{J}$. Rotational: $I = \tfrac{2}{5}(0.5)(0.5)^{2} = 0.05$, $\omega = v/R = 10\ \text{rad/s}$, giving $\tfrac{1}{2}(0.05)(100) = 2.5\ \text{J}$. Total $= 8.75\ \text{J}$.', 'Total Kinetic Energy of a Rolling Body', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Which of the following is NOT true about torque?', '["It is a vector","It produces a turning effect","It is energy","Its unit is N m"]'::jsonb, 2, 'Torque is the turning effect of a force. It has the same unit as energy (N m) but it is not energy.', 'Torque - Concepts', false, 'first', 3);

-- Exact-duplicate check against the rest of the bank (should return 0 rows).
select question, count(*) from public.cbt_questions
 where subject_id = 'phy-121-mechanics'
 group by question having count(*) > 1;


-- ============================================================
-- PART 2 of 6: link_phy121_to_phy101_phy103.sql
-- ============================================================
-- Old PHY 121 (Fundamentals of Physics I) = new PHY 101 + new PHY 103
-- =============================================================================
-- Confirmed by the user: the old PHY 121 course has split into
--   PHY 101  Mechanics (units and dimensions through static equilibrium)
--   PHY 103  Properties of Matter (elasticity, fluids, surface tension,
--            viscosity, ideal gas laws and kinetic theory)
-- RUN ORDER: (1) unn_phy101_ca_cbt_questions.sql  (2) this file.
--
-- A. CBT: the mechanics subject keeps its id 'phy-121-mechanics' (so existing
--    attempts and unlocks are not orphaned) and is displayed as PHY 101. The
--    properties-of-matter questions move to a new subject, 'phy-103-properties-of-matter'.
--    Questions are moved by topic.
-- B. Course outlines: ADDITIVE ONLY. New PHY 101 and PHY 103 rows are added for
--    every department that has a PHY 121 row. The PHY 121 rows are kept.
--    Credit units are set to 0 (unknown) rather than guessed; please confirm.
-- =============================================================================

-- A1. Display name of the mechanics bank
update public.cbt_questions
   set subject_name = 'PHY 101: Fundamentals of Physics I (Mechanics)'
 where subject_id = 'phy-121-mechanics';

-- A2. Move the properties-of-matter questions to PHY 103
update public.cbt_questions
   set subject_id = 'phy-103-properties-of-matter',
       subject_name = 'PHY 103: Properties of Matter, Fluids and Kinetic Theory'
 where subject_id = 'phy-121-mechanics'
   and replace(topic, ' [VERIFY]', '') in (
     'Hooke''s Law',
     'Elastic Potential Energy',
     'Young''s Modulus',
     'Hooke''s Law (Stress-Strain)',
     'Ductile and Brittle Materials',
     'Torsional Strain and Shear Modulus',
     'Bulk Modulus of Elasticity',
     'Compressibility',
     'Pressure in Liquids',
     'Characteristics of Liquid Pressure',
     'Mercury Barometer',
     'Hydraulic Press',
     'Hydraulic Press Principle',
     'Siphon',
     'Density of Mixtures',
     'Relative Density',
     'Archimedes'' Principle',
     'Archimedes'' Principle (Tension)',
     'Principle of Flotation',
     'Hydrometers',
     'Surface Tension',
     'Reduction of Surface Tension',
     'Capillary Rise',
     'Capillarity (Tube Diameter)',
     'Excess Pressure in a Liquid Drop',
     'Excess Pressure in a Soap Bubble',
     'Equation of Continuity',
     'Bernoulli''s Equation',
     'Bernoulli''s Principle',
     'Torricelli''s Theorem',
     'Bernoulli''s Equation (Lift)',
     'Venturi Flow Meter',
     'Fluid Viscosity',
     'Viscosity (Viscometer)',
     'Poiseuille''s Equation',
     'Stokes'' Law',
     'Terminal Velocity',
     'Reynolds Number',
     'Compressibility of Water',
     'Flow Speed from Flow Rate',
     'Continuity Equation with Reduced Diameter',
     'Reynolds Number and Kinematic Viscosity',
     'Boyle''s Law',
     'Charles'' Law',
     'Ideal Gas Equation',
     'Ideal Gas Equation (Moles Used)',
     'Kinetic Theory Assumptions',
     'Kinetic Theory Pressure Equation',
     'Kinetic Theory and Temperature',
     'Root Mean Square Speed',
     'R.M.S. Speed and Molecular Mass',
     'Graham''s Law of Diffusion',
     'Dalton''s Law of Partial Pressures',
     'Avogadro''s Law',
     'Average Kinetic Energy of Gas Molecules',
     'Avogadro''s Number',
     'Elastic properties of solids',
     'Surface tension and viscosity',
     'Fluid mechanics and hydrodynamics',
     'Ideal gas laws and kinetic theory of gases'
   );

-- A3. Check: both counts should be above zero
select subject_id, subject_name, count(*) as questions
  from public.cbt_questions
 where subject_id in ('phy-121-mechanics', 'phy-103-properties-of-matter')
 group by 1, 2 order by 1;

-- B1. PHY 101 outline rows (from each PHY 121 row)
insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level, semester,
   credit_units, description, topics, contributor_name, is_elective)
select 'PHY 101', 'Mechanics (Fundamentals of Physics I)', o.institution, o.faculty, o.department,
       o.level, o.semester, 0,
       'Units and dimensions. Vector algebra. Kinematics and dynamics of a mass point; laws of mechanics and gravitation, Kepler''s Laws. Motion of rigid bodies, moment of inertia; angular momentum - conservation laws. Static equilibrium of rigid bodies. Circular and simple harmonic motion.',
       '["Units and dimensions", "Vector algebra", "Kinematics and dynamics of a mass point", "Laws of mechanics and gravitation, Kepler''s Laws", "Motion of rigid bodies, moment of inertia", "Angular momentum - conservation laws", "Static equilibrium of rigid bodies", "Circular and simple harmonic motion"]'::jsonb,
       'Department of Physics and Astronomy handbook (split from PHY 121)', false
  from public.course_outlines o
 where o.course_code = 'PHY 121'
   and o.institution = 'University of Nigeria, Nsukka'
   and not exists (select 1 from public.course_outlines x
                    where x.course_code = 'PHY 101' and x.institution = o.institution
                      and x.department = o.department and x.faculty = o.faculty);

-- B2. PHY 103 outline rows (from each PHY 121 row)
insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level, semester,
   credit_units, description, topics, contributor_name, is_elective)
select 'PHY 103', 'Properties of Matter (Fundamentals of Physics I)', o.institution, o.faculty, o.department,
       o.level, o.semester, 0,
       'Elastic properties of solids, moduli of elasticity. Surface tension, viscosity. Fluid mechanics and hydrodynamics. Ideal gas laws. Kinetic theory of gases.',
       '["Elastic properties of solids, moduli of elasticity", "Surface tension, viscosity", "Fluid mechanics and hydrodynamics", "Ideal gas laws", "Kinetic theory of gases"]'::jsonb,
       'Department of Physics and Astronomy handbook (split from PHY 121)', false
  from public.course_outlines o
 where o.course_code = 'PHY 121'
   and o.institution = 'University of Nigeria, Nsukka'
   and not exists (select 1 from public.course_outlines x
                    where x.course_code = 'PHY 103' and x.institution = o.institution
                      and x.department = o.department and x.faculty = o.faculty);

-- B3. Check: new rows per department
select course_code, faculty, department, credit_units
  from public.course_outlines
 where course_code in ('PHY 101', 'PHY 103')
   and contributor_name like '%split from PHY 121%'
 order by faculty, department, course_code;


-- ============================================================
-- PART 3 of 6: unn_phy107_practical_physics_1_cbt_questions.sql
-- ============================================================
-- PHY 107 (new code) = PHY 191 / 193 (old codes): General Physics Practical I
-- =============================================================================
-- New CBT subject 'phy-107-practical-physics-1' with 154 questions built from the
-- PHY 191 / PHY 191-193 past questions (2019/2020 and 2017/2018 sessions) and
-- the "more questions" set that follows them.
--
-- ASSUMPTIONS (please confirm): PHY 107 = first semester, 1 unit, 100 Level,
-- same faculties as the PHY 108 practical (Physical Sciences, Engineering,
-- Biological Sciences, Veterinary Medicine, Environmental Studies).
--
-- Every printed answer was re-checked. Answers that were wrong in the source
-- were corrected (relative density in 2019 Q1, water pressure in a half-filled
-- tank, flask density, Boyle's-law pressure, thermometer reading, density
-- conversion, reading accuracy of a metre rule). Questions with no correct
-- option, a missing figure or a garbled formula were dropped (the list is in
-- the generator notes). The source's website watermark and advert lines
-- are not used. Repeated stems are kept once.
-- =============================================================================
insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general,
   semester, units)
values
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'What is the relative density of a liquid if an object weighs 20N in air, 17N when totally immersed in water and 18N when totally immersed in the liquid?', '["1.5","0.67","0.94","1.05"]'::jsonb, 1, 'Relative density $= (W_{air} - W_{liquid})/(W_{air} - W_{water}) = (20 - 18)/(20 - 17) = 2/3 \approx 0.67$.', 'Density and Flotation', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The general equation of a straight line graph is given as:', '["Y = Mx + C","Y = Mx² + C","Y = Mx + c²","Y = M + Cx"]'::jsonb, 0, 'The correct answer is: Y = Mx + C.', 'Graphs and Linearisation', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Internal diameter of an object is measured by:', '["Vernier Calliper","Screw Gauge","External Jaws","Internal Jaws"]'::jsonb, 0, 'The correct answer is: Vernier Calliper.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Uncertainties encountered in making observations are known as:', '["Precision","Reliability","Errors","Accuracy"]'::jsonb, 2, 'The correct answer is: Errors.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'An object has a specific heat capacity of 200J/Kg/°C. If 1x10⁵J of energy is required to change its temperature from 20°C to 70°C, determine its mass:', '["100Kg","27Kg","17.5Kg","10Kg"]'::jsonb, 3, '$m = Q/(c\Delta T) = 10^{5}/(200\times50) = 10\ \text{kg}$.', 'Heat and Thermometry', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The heat transfer reaches us through:', '["Conduction","Radiation","Convection","Reflection"]'::jsonb, 1, 'The correct answer is: Radiation.', 'Heat and Thermometry', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Vernier calliper has two scales:', '["Vernier scale and mid scale","Main scale and minor scale","Main and vernier scale","None of the above"]'::jsonb, 2, 'The correct answer is: Main and vernier scale.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The number of significant figures in 4.07x10¹⁵m is:', '["1","3","14","15"]'::jsonb, 1, 'In $4.07\times10^{15}$ the significant figures are 4, 0 and 7, so there are 3.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A small bob of mass 20g oscillate as a simple pendulum with amplitude 5cm and a period of 2 seconds. Find the velocity of the bob when the velocity is maximum:', '["0.05ms⁻¹","3.14ms⁻¹","0.16ms⁻¹","0.001ms⁻¹"]'::jsonb, 2, 'Maximum speed $v = A\omega = A(2\pi/T) = 0.05\times\pi \approx 0.16\ \text{m/s}$.', 'Simple Harmonic Motion', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A Vapour whose molecules are in dynamic equilibrium with those of its liquids is said to be:', '["Saturated","Unsaturated","Gaseous","Diffused"]'::jsonb, 0, 'The correct answer is: Saturated.', 'Heat and Thermometry', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Which instrument is used to measure the relative density of a liquid?', '["Hygrometer","Hydrometer","Thermometer","Barometer"]'::jsonb, 1, 'The correct answer is: Hydrometer.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'If a simple pendulum performing SHM swings to maximum amplitude, its kinetic energy is:', '["Zero","Maximum","Twice its potential","Equal to its potential"]'::jsonb, 0, 'The correct answer is: Zero.', 'Simple Harmonic Motion', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'In an experiment, the vernier calliper was used to measure the breadth to be 2.40cm and the thickness to be 0.45cm of the metre rule. Find the volume of the metre rule:', '["123.0cm","105.0cm","108.0cm","109.0cm"]'::jsonb, 2, 'The metre rule is $100\ \text{cm}$ long: $V = 100\times2.40\times0.45 = 108\ \text{cm}^{3}$.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Given that L = 20.00±0.05 and w = 15.00±0.05cm, What is the maximum error in the sum:', '["0.1cm","0.01cm","0.05cm","0.001cm"]'::jsonb, 0, 'Maximum errors add for a sum: $0.05 + 0.05 = 0.1\ \text{cm}$.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The relation between current $I$, e.m.f. $E$, external resistance $R$ and internal resistance $r$ is $I = E/(R + r)$, where $I$ and $R$ are variables and $E$ and $r$ are constants. Transform it to the form $y = mx + c$:', '["$1/I = R(1/E) + r/E$","$1/I = 1/R + IE$","$r/I = 1/I + 1/E$","$EI = 1/(R + r)$"]'::jsonb, 0, 'The correct answer is: 1/I = R(1/E) + r/E.', 'Electricity', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'For $I = E/(R + r)$ written in the form $y = mx + c$ by plotting against $R$, what is $y$?', '["$1/I$","$r/E$","$r/R$","$IE$"]'::jsonb, 0, 'The correct answer is: 1/I.', 'General Practical Physics', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'For $I = E/(R + r)$ written in the form $y = mx + c$, what is $x$?', '["$1/I$","$R$","$r/E$","$1/E$"]'::jsonb, 1, 'The correct answer is: R.', 'General Practical Physics', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'For $1/I = (1/E)R + r/E$ plotted as $y = mx + c$, the intercept is:', '["$r/B$","$Rr/I$","$1/E$","$r/E$"]'::jsonb, 3, 'The correct answer is: r/E.', 'Graphs and Linearisation', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'What is the reading accuracy of a vernier calliper:', '["0.1cm","0.001cm","0.01cm","0.0001cm"]'::jsonb, 2, 'The correct answer is: 0.01cm.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The circular scale of a micrometer screw gauge is divided into 100 equal parts and the spindle moves $0.5\ \text{mm}$ in one revolution. The pitch of the gauge is:', '["$100\\ \\text{mm}$","$0.01\\ \\text{mm}$","$0.5\\ \\text{mm}$","$25\\ \\text{mm}$"]'::jsonb, 2, 'The correct answer is: 0.5\ \text{mm}.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The circular scale of a micrometer screw gauge is divided into 100 equal parts and the spindle moves $0.5\ \text{mm}$ in one revolution. The least count of the gauge is:', '["$0.5\\ \\text{mm}$","$0.05\\ \\text{mm}$","$0.1\\ \\text{mm}$","$0.005\\ \\text{mm}$"]'::jsonb, 3, 'The correct answer is: 0.005\ \text{mm}.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A graduated cylinder is marked every millilitre. How precise a measurement can you make with this instrument:', '["±1mL","±0.5mL","±1.0mL","±0.5cL"]'::jsonb, 1, 'The correct answer is: ±0.5mL.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Given $X = 10.10 \pm 0.05$, $Y = 6.03 \pm 0.01$ and $Z = 3.04 \pm 0.02$, and $U = X + Y + Z$, the value of $U$ with its maximum error is:', '["$19.17 \\pm 0.08$","$13.094 \\pm 0.3$","$13.094 \\pm 0.2$","$19.094 \\pm 0.2$"]'::jsonb, 0, 'Sum $= 19.17$. Maximum error $= 0.05 + 0.01 + 0.02 = 0.08$.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Given $X = 10.10 \pm 0.05$, $Y = 6.03 \pm 0.01$ and $Z = 3.04 \pm 0.02$, and $U = X + Y + Z$, the value of $U$ with its standard error (addition in quadrature) is:', '["$19.09 \\pm 0.03$","$19.17 \\pm 0.06$","$19.27 \\pm 0.08$","None of the above"]'::jsonb, 1, 'Standard error $= \sqrt{0.05^{2} + 0.01^{2} + 0.02^{2}} = \sqrt{0.003} \approx 0.055 \approx 0.06$.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Least count of screw gauge is:', '["0.01cm","0.5cm","0.1cm","0.01mm"]'::jsonb, 3, 'The correct answer is: 0.01mm.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The length and width of an object are $L = 20.00 \pm 0.05\ \text{cm}$ and $W = 15.00 \pm 0.05\ \text{cm}$. The sum $L + W$ should be reported as:', '["$35.0\\ \\text{cm}$","$35.0 \\pm 0.01\\ \\text{cm}$","$35.001\\ \\text{cm}$","$35.0 \\pm 0.1\\ \\text{cm}$"]'::jsonb, 3, 'The correct answer is: 35.0 \pm 0.1\ \text{cm}.', 'General Practical Physics', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'For $L = 20.00 \pm 0.05\ \text{cm}$ and $W = 15.00 \pm 0.05\ \text{cm}$, the maximum error in the sum $L + W$ is:', '["$0.1\\ \\text{cm}$","$\\pm0.01\\ \\text{cm}$","$\\pm0.1\\ \\text{cm}$","$\\pm0.001\\ \\text{cm}$"]'::jsonb, 2, 'The correct answer is: \pm0.1\ \text{cm}.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Internal diameter of a beaker can be accurately measured using:', '["Internal jaws of a Vernier caliper","Micrometer screw gauge","A meter-rule","External jaws of a vernier caliper"]'::jsonb, 0, 'The correct answer is: Internal jaws of a Vernier caliper.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Vernier callipers has two scales namely:', '["Main and vernier scale","Vernier scale and mid scales","Main and minor scale","Main and circular scale"]'::jsonb, 0, 'The correct answer is: Main and vernier scale.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'If density of water is 1000Kg/m³, acceleration due to gravity is 10.0m/s², the pressure due to water at the bottom of a 20m deep tank which is half filled is:', '["1000kpa","100kpa","10kpa","200kpa"]'::jsonb, 1, 'The tank is half filled, so the water depth is $10\ \text{m}$. $P = \rho gh = 1000\times10\times10 = 1.0\times10^{5}\ \text{Pa} = 100\ \text{kPa}$.', 'Density and Flotation', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A useful instrument for the direct measurement of the weight of an object is:', '["Beam balance","Spring balance","Top loading balance","Lever balance"]'::jsonb, 1, 'The correct answer is: Spring balance.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'If a simple pendulum performing simple harmonic motion swings to maximum amplitude, its kinetic energy is:', '["Maximum","Twice its potential energy","Equal to its potential energy","Zero"]'::jsonb, 3, 'The correct answer is: Zero.', 'Simple Harmonic Motion', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The density $0.2\ \text{g/cm}^{3}$ in S.I. units is:', '["$0.2\\times10^{3}\\ \\text{kg/m}^{3}$","$0.2\\ \\text{kg/cm}^{3}$","$2.0\\ \\text{kg/cm}^{3}$","$2000\\ \\text{kg/m}^{3}$"]'::jsonb, 0, '$0.2\ \text{g/cm}^{3} = 0.2\times10^{3}\ \text{kg/m}^{3} = 200\ \text{kg/m}^{3}$.', 'Density and Flotation', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Barrel of screw gauge has:', '["50 divisions","100 divisions","10 divisions","45 divisions"]'::jsonb, 1, 'The correct answer is: 100 divisions.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Digital stopwatches show reading up to:', '["3 decimal places","Decimal place","4 significant figure","2 decimal places"]'::jsonb, 3, 'The correct answer is: 2 decimal places.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Error due to manually stopping a stopwatch is termed as:', '["Climax error","Human reaction error","Rateability error","Human reaction time"]'::jsonb, 1, 'The correct answer is: Human reaction error.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'In SHM of a simple pendulum, component of weight which is directed towards mean position is:', '["mg cosθ","0","mg tanθ","mg sinθ"]'::jsonb, 3, 'The correct answer is: mg sinθ.', 'Simple Harmonic Motion', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Error that occurs due to equally affected measurements is called:', '["Random error","Frequent error","Precision","Systematic error"]'::jsonb, 3, 'The correct answer is: Systematic error.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Systematic error that occurred due to poor calibration of instrument that can be corrected by:', '["Taking several readings","Replacing instruments","Taking mean of values","Taking median of values"]'::jsonb, 1, 'The correct answer is: Replacing instruments.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A group of students are told to use a meter stick to find the length of a hallway. They make 6 independent measurements: 4.402 m, 4.217 m, 4.345 m, 4.925 m, 4.372 m, 4.289 m. How should they report their best estimate of the length of the hallway?', '["L = 4.43 ± 0.25 m","L = 4.325 ± 0.073 m","L = 4.425 ± 0.104 m","L = 4.33 ± 0.03 m"]'::jsonb, 2, 'Mean $= 4.425\ \text{m}$. The sample standard deviation is $0.254\ \text{m}$, so the standard error is $0.254/\sqrt{6} \approx 0.104\ \text{m}$.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A student uses a protractor to measure an angle to be A = 82° ± 1°. What should she report for sin(A)?', '["sin(A) = 0.990 ± 0.002","sin(A) = 1.0 ± 0.2","sin(A) = 0.99 ± 0.02","sin(A) = 0.9903 ± 0.0024"]'::jsonb, 3, '$\sin82^{\circ} = 0.9903$. The error is $\cos82^{\circ}\times(1^{\circ}$ in radians$) = 0.139\times0.01745 \approx 0.0024$.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A student drops a baseball from a height $h = 5.25 \pm 0.15\ \text{m}$ and measures an average fall time $t = 1.14 \pm 0.06\ \text{s}$. Using $a = 2h/t^{2}$, the average acceleration and its uncertainty (errors combined in quadrature) are:', '["$8.08 \\pm 0.1\\ \\text{m/s}^{2}$","$8.08 \\pm 0.88\\ \\text{m/s}^{2}$","$8.1 \\pm 0.9\\ \\text{m/s}^{2}$","$8.08 \\pm 0.06\\ \\text{m/s}^{2}$"]'::jsonb, 1, '$a = 2(5.25)/1.14^{2} = 8.08$. Fractional errors: $h$: $0.15/5.25 = 0.029$; $t$ (counted twice): $2(0.06/1.14) = 0.105$. In quadrature: $\sqrt{0.029^{2} + 0.105^{2}} = 0.109$, giving $\pm0.88$.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The rate of change of bending moment is equal to:', '["Stress","Deflection","Strain","Shear force"]'::jsonb, 3, 'The correct answer is: Shear force.', 'General Practical Physics', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A cantilever beam of span 3m carries a point load 100N at the free end. The maximum bending moment in the beam will be:', '["100 N-m","300 N-m","150 N-m","600 N-m"]'::jsonb, 1, 'The maximum bending moment of a cantilever with an end load is $WL = 100\times3 = 300\ \text{N m}$.', 'General Practical Physics', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The reading accuracy of a meter rule is:', '["0.2cm","0.5cm","0.1cm","0.01cm"]'::jsonb, 2, 'A metre rule is graduated in millimetres, so the reading accuracy is $0.1\ \text{cm}$.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'If two quantities are inversely proportional then graph between y and 1/x gives:', '["Straight line cutting y-axis","A parabolic curve","A hyperbolic curve","Straight line through origin"]'::jsonb, 3, 'The correct answer is: Straight line through origin.', 'Graphs and Linearisation', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A set of independent current measurements recorded as 10.03, 10.10, 10.11 and 10.08. The average range of error in the current is:', '["10.08 A","0.03 A","0.04 A","0.05 A"]'::jsonb, 2, 'The average range (half the spread) is $(10.11 - 10.03)/2 = 0.04\ \text{A}$.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'In a science lab, a student heats up a chemical from 10°C to 25°C which requires thermal energy of 30000J. If mass of object is 40kg, specific heat capacity of chemical would be:', '["25 J·kg⁻¹·°C⁻¹","75 J·kg⁻¹·°C⁻¹","100 J·kg⁻¹·°C⁻¹","50 J·kg⁻¹·°C⁻¹"]'::jsonb, 3, '$c = Q/(m\Delta T) = 30000/(40\times15) = 50\ \text{J kg}^{-1}\,^{\circ}\text{C}^{-1}$.', 'Heat and Thermometry', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A 250cm³ flask of glass filled with seawater weighs 350g. Density of seawater if empty flask weighs 100g would be:', '["5/7 g/cm³","5/3 g/cm³","5/g cm³","1 g/cm³"]'::jsonb, 3, 'Mass of seawater $= 350 - 100 = 250\ \text{g}$. Density $= 250/250 = 1\ \text{g/cm}^{3}$.', 'Density and Flotation', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Air trapped inside a single-piston-cylinder exerts a pressure of 760 mmHg. If its volume is increased by 20% at constant temperature, pressure exerted would be equal to:', '["533 mmHg","544 mmHg","534 mmHg","633 mmHg"]'::jsonb, 3, 'Boyle''s law: $P_2 = P_1V_1/V_2 = 760/1.2 \approx 633\ \text{mmHg}$.', 'Heat and Thermometry', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A mercury thermometer was calibrated: ice point corresponds to 3cm while steam point corresponds to 30cm of mercury. If length = 10cm, the temperature corresponds to:', '["26°C","22°C","20°C","24°C"]'::jsonb, 0, 'Temperature $= (10 - 3)/(30 - 3)\times100 = 25.9 \approx 26\,^{\circ}\text{C}$.', 'Heat and Thermometry', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A particle of mass m oscillates in a straight line with SHM of constant amplitude. The total energy of the particle is E. What is the total energy of another particle of mass 2m, oscillating with SHM of the same amplitude but double the frequency?', '["8E","2E","2ED","4E"]'::jsonb, 0, 'Total energy $E = \tfrac{1}{2}m\omega^{2}A^{2}$. Doubling the mass and the frequency (so $\omega^{2}$ is four times) gives $2\times4 = 8$ times the energy.', 'Graphs and Linearisation', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', '10 Km/hr in S.I units is:', '["2m/s","0.5m/s","2.8m/s","10m/s"]'::jsonb, 2, '$10\ \text{km/h} = 10\times1000/3600 \approx 2.8\ \text{m/s}$.', 'General Practical Physics', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A spherical ball falls 60cm through a viscous liquid in 1.2 seconds. Its velocity is:', '["5m/s","60cm/s","0.5m/s","50cm/min"]'::jsonb, 2, '$v = 60\ \text{cm}/1.2\ \text{s} = 50\ \text{cm/s} = 0.5\ \text{m/s}$.', 'Mechanics', false, 'first', 1),
