  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A student records the following values: 2.5, 2.7, 2.4, 2.6 cm. The mean value is:', '["2.4 cm","2.5 cm","2.6 cm","2.55 cm"]'::jsonb, 3, 'Mean $= (2.5 + 2.7 + 2.4 + 2.6)/4 = 2.55\ \text{cm}$.', 'General Practical Physics', false, 'first', 1),
